import fs from 'fs';

// These files are generated by the content-creator skill for local use and are
// not referenced by the production site. Removing them from dist/ saves ~1.8 MB.
const files = [
  'dist/assets/content/index-en.json',
  'dist/assets/content/index-es.json',
];

for (const f of files) {
  try {
    fs.rmSync(f);
    console.error(`Removed ${f}`);
  } catch (e) {
    if (e.code !== 'ENOENT') throw e;
  }
}
